// src/motion/cubic-morph.js
function interpolateCubics([from, to], progress) {
  return from.map((segment, i) => segment.map((value, j) => value + (to[i][j] - value) * progress));
}
function drawMorph(ctx, pair, progress, scale2) {
  const cubics = interpolateCubics(pair, progress);
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const c of cubics) for (let i = 0; i < 8; i += 2) {
    minX = Math.min(minX, c[i]);
    maxX = Math.max(maxX, c[i]);
    minY = Math.min(minY, c[i + 1]);
    maxY = Math.max(maxY, c[i + 1]);
  }
  const x = (minX + maxX) / 2, y2 = (minY + maxY) / 2;
  ctx.beginPath();
  ctx.moveTo((cubics[0][0] - x) * scale2, (cubics[0][1] - y2) * scale2);
  for (const c of cubics) ctx.bezierCurveTo(
    (c[2] - x) * scale2,
    (c[3] - y2) * scale2,
    (c[4] - x) * scale2,
    (c[5] - y2) * scale2,
    (c[6] - x) * scale2,
    (c[7] - y2) * scale2
  );
  ctx.closePath();
  ctx.fill();
}

